package com.henson.jarvis.phone;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.security.*;import java.security.interfaces.RSAPublicKey;import java.util.*;import java.nio.charset.StandardCharsets;import org.json.*;
@RunWith(AndroidJUnit4.class)
public class AuthSecurityTest {
 private KeyPair pair;private JSONObject keys;private String client="test-client",nonce="test-nonce";
 @Before public void setup()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);pair=g.generateKeyPair();RSAPublicKey p=(RSAPublicKey)pair.getPublic();keys=new JSONObject().put("keys",new JSONArray().put(new JSONObject().put("kid","test").put("kty","RSA").put("n",b64(p.getModulus().toByteArray())).put("e",b64(p.getPublicExponent().toByteArray()))));}
 private String b64(byte[] data){return Base64.getUrlEncoder().withoutPadding().encodeToString(data);}
 private JSONObject claims()throws Exception{return new JSONObject().put("iss","https://auth.openai.com").put("aud",client).put("nonce",nonce).put("sub","test-subject").put("exp",System.currentTimeMillis()/1000+600);}
 private String token(JSONObject claims)throws Exception{String data=b64(new JSONObject().put("alg","RS256").put("kid","test").toString().getBytes(StandardCharsets.UTF_8))+"."+b64(claims.toString().getBytes(StandardCharsets.UTF_8));Signature s=Signature.getInstance("SHA256withRSA");s.initSign(pair.getPrivate());s.update(data.getBytes(StandardCharsets.US_ASCII));return data+"."+b64(s.sign());}
 private void rejected(JSONObject c)throws Exception{try{OAuthChecks.verify(token(c),keys,client,nonce,System.currentTimeMillis()/1000);fail("Invalid identity must be rejected");}catch(Exception expected){}}
 @Test public void verifiesSignedIdentity()throws Exception{assertEquals("test-subject",OAuthChecks.verify(token(claims()),keys,client,nonce,System.currentTimeMillis()/1000).getString("sub"));}
 @Test public void rejectsWrongNonceAudienceIssuerAndExpiry()throws Exception{rejected(claims().put("nonce","wrong"));rejected(claims().put("aud","other-client"));rejected(claims().put("iss","https://attacker.invalid"));rejected(claims().put("exp",1));}
 @Test public void rejectsUntrustedSignature()throws Exception{String signed=token(claims());KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);pair=g.generateKeyPair();try{OAuthChecks.verify(token(claims()),keys,client,nonce,System.currentTimeMillis()/1000);fail("Forged signature accepted");}catch(Exception expected){}assertNotNull(signed);}
 @Test public void requiresPlanScopesAndState()throws Exception{try{OAuthChecks.scopes("openid profile email");fail("Identity-only grant accepted");}catch(Exception expected){}try{OAuthChecks.same("expected","forged");fail("State mismatch accepted");}catch(Exception expected){}OAuthChecks.scopes("resource.invoke chatgpt.tokens.use.direct");}
 @Test public void pkceMatchesPublishedRfcVector()throws Exception{assertEquals("E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM",OAuthChecks.challenge("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"));}
 @Test public void vaultEncryptsCredentialsAndKeepsHostStable()throws Exception{android.content.Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();TokenVault vault=new TokenVault(c);assertEquals(vault.host(),vault.host());JSONObject data=new JSONObject().put("accounts",new JSONObject()).put("test","fake-secret-for-test");vault.write(data);String stored=c.getSharedPreferences("jarvis-private",0).getString("accounts","");assertFalse(stored.contains("fake-secret-for-test"));assertEquals("fake-secret-for-test",vault.read().getString("test"));vault.write(new JSONObject().put("accounts",new JSONObject()));}
}
